{
  "items": [
    {
      "title": "ACLED – Armed Conflict Location & Event Data: Protest Events in Germany (2020–2026)",
      "url_or_doi": "https://acleddata.com/conflict-data/data-export-tool",
      "justification": "A major event-level dataset documenting protests, demonstrations, riots, and political violence across Germany, including Berlin, from 2020 onward. Records include event dates, geographic locations, actors, protest types, and descriptions. Particularly useful for examining the 2024 farmers' protests, climate activism, environmental movements, and demonstrations concerning agricultural and food policy. Data can be filtered by Germany, Berlin, date, and event category."
    },
    {
      "title": "POLIZEI STRESSI – Berlin Demonstrations and Assemblies Dataset (2021–2026)",
      "url_or_doi": "https://polizeistressi.de/data/",
      "justification": "An archive of official Berlin police registration data covering demonstrations and public assemblies since 2021. Includes dates, locations, demonstration topics, and geographic distributions. Particularly relevant for identifying agricultural protests, farmers' demonstrations, climate activism, and food-policy mobilization in Berlin. The dataset supports analysis of protest frequency, geographic concentration, and changes in mobilization over time."
    },
    {
      "title": "German Protest Registrations – Demonstrations in German Cities",
      "url_or_doi": "https://github.com/davidpomerenke/german-protest-registrations",
      "justification": "A research dataset compiling administrative records of registered demonstrations in German cities. It provides information about protest events and their characteristics, offering an alternative to media-based protest event datasets. Useful for comparing protest mobilization across German cities and investigating the geographic distribution of demonstrations related to agricultural policy, environmental regulation, and broader political movements."
    },
    {
      "title": "Berlin Open Data – Registered Public Assemblies (Versammlungen im Land Berlin)",
      "url_or_doi": "https://www.govdata.de/suche/daten/versammlungen-im-land-berlin?ids=0e013066-6e31-4950-b28b-af326081c502&ids=730727c7-0144-4798-9f7f-9aee96fae017&ids=bb2aa74b-ed74-4137-8273-736b2e515681",
      "justification": "An official German government data catalog entry for registered public assemblies in Berlin. Relevant for studying the spatial and temporal distribution of demonstrations and identifying protests concerning agricultural subsidies, farming conditions, food systems, and environmental policy. Provides an official administrative source that can complement ACLED records."
    },
    {
      "title": "FragDenStaat – Berlin Demonstrations and Assemblies, 2023–2024",
      "url_or_doi": "https://fragdenstaat.de/anfrage/versammlungen-2023-und-2024/",
      "justification": "A freedom-of-information request seeking detailed Berlin assembly records for 2023 and 2024, including dates, locations, and demonstration purposes where available. Particularly relevant to the major German farmers' protests in January 2024. This is a data-access request rather than a guaranteed downloadable dataset; the associated records and responses should be checked for availability."
    },
    {
      "title": "GESIS – Right-Wing Extremist Mobilization in Germany",
      "url_or_doi": "https://doi.org/10.7802/2774",
      "justification": "A research dataset on right-wing extremist demonstrations and political mobilization in Germany, with data collection extending into the 2020s. Useful for studying relationships between protest movements, political radicalization, and mobilization around government policy. It can provide contextual information when examining the political environment surrounding agricultural protests, although it does not specifically measure agricultural or nutrition policy."
    },
    {
      "title": "ProLoc – German Local Protest Dataset (2000–2020)",
      "url_or_doi": "https://b2find.eudat.eu/dataset/4b084c93-d1f6-557d-a806-2c93e8af21ad",
      "justification": "A systematic protest-event dataset covering Bremen, Dresden, Leipzig, and Stuttgart through 2020. Includes protest forms, demands, organizers, and participating social groups. Useful for establishing historical baselines and comparing early-2020 protest activity with later agricultural and environmental movements. Geographic coverage does not include Berlin, and coverage of the 2020s is limited to 2020."
    },
    {
      "title": "Institute for Protest and Social Movement Studies – Harmonized Protest Survey Data",
      "url_or_doi": "https://protestinstitut.eu/en/20-years-of-protest-surveys-ipb-publishes-protest-survey-data/",
      "justification": "A collection of 31 harmonized protest surveys from Germany and Poland, announced in 2026. The surveys provide participant-level information about motivations, political attitudes, and sociodemographic characteristics. Relevant for understanding who participates in German protest movements and why. Individual survey dates and protest topics should be checked before selecting data for agricultural or nutrition-policy research."
    },
    {
      "title": "European Commission – Common Agricultural Policy 2023–2027 Performance Monitoring and Evaluation Indicators",
      "url_or_doi": "https://agridata.ec.europa.eu/extensions/Dataportal/pmef_indicators.html",
      "justification": "An official European Commission data portal containing indicators measuring implementation and performance of the Common Agricultural Policy (CAP) during 2023–2027. Germany-specific data can be selected to examine agricultural subsidies, environmental objectives, rural development, planned interventions, and policy outcomes. Especially useful for connecting agricultural protest movements with changes in agricultural policy and public funding."
    },
    {
      "title": "European Commission – CAP 2023–2027 Indicators and Reporting Methodology",
      "url_or_doi": "https://agridata.ec.europa.eu/extensions/DataPortal/pmef-indicators-info.html",
      "justification": "Official documentation and access information for CAP output, result, context, and impact indicators. Provides information on agricultural support measures, implementation years, and policy monitoring. Useful for correctly interpreting German agricultural policy datasets, including the distinction between claim years and financial years. This is primarily a methodological and data-access resource rather than a standalone dataset."
    },
    {
      "title": "European Commission – Agri-food Data Portal",
      "url_or_doi": "https://agridata.ec.europa.eu/extensions/Dataportal/help.html",
      "justification": "An official entry point for European agricultural and food-system datasets, including agricultural markets, food supply, agricultural income, EU financing, and CAP implementation. Germany-specific indicators can help researchers investigate the economic context of agricultural protests, food prices, agricultural production, and the relationship between farming policies and food-system outcomes."
    },
    {
      "title": "Destatis GENESIS-Online – German Agricultural Statistics",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistics",
      "justification": "Germany's official statistical database provides downloadable agricultural statistics, including farm structures, agricultural production, land use, livestock, and economic indicators. Many statistical series cover the 2020s and offer geographic breakdowns. Useful for measuring structural changes in German agriculture and assessing economic pressures associated with agricultural protests. Data can be downloaded in CSV and spreadsheet formats."
    },
    {
      "title": "Destatis – Agricultural Census 2020 (Landwirtschaftszählung 2020)",
      "url_or_doi": "https://lz2020.statistikportal.de",
      "justification": "The official German Agricultural Census provides detailed information on agricultural enterprises, land use, livestock, farm structures, and agricultural employment in 2020. It offers an important baseline for examining structural conditions preceding the 2023–2024 agricultural protests. Regional statistics can support comparisons between Berlin, Brandenburg, and Germany as a whole."
    },
    {
      "title": "Destatis – GENESIS-Online Open Data and API",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/api-webservice.html",
      "justification": "An official interface for programmatically accessing German statistical datasets. Particularly useful for constructing longitudinal datasets covering agricultural production, food-related economic indicators, and regional agricultural structures during the 2020s. The REST API enables reproducible extraction of agricultural and related statistics for quantitative policy analysis."
    },
    {
      "title": "Robert Koch Institute – German Health Update (GEDA 2019/2020-EHIS)",
      "url_or_doi": "https://doi.org/10.7797/31-201920-1-1-1",
      "justification": "A nationally representative German health survey containing 22,708 observations and 310 variables, collected between 2019 and 2020. Relevant for studying nutrition-related health outcomes, overweight, obesity, and health inequalities. Scientific-use data include federal-state geographic information, enabling analysis of Berlin relative to Germany. Access to individual-level research data is subject to the institute's data-use procedures."
    },
    {
      "title": "Robert Koch Institute – Scientific Use Files for German Population Health Surveys",
      "url_or_doi": "https://www.rki.de/EN/News/Publications/Research-data/Scientific-Use-Files/Data-records/data-records-node.html",
      "justification": "An official catalog of scientific-use datasets from German population health surveys, including GEDA and other health-monitoring studies. Relevant variables can support research on dietary behavior, obesity, health inequalities, and nutrition-related policy outcomes. Geographic detail varies by dataset, and some surveys provide federal-state comparisons. This resource is especially useful for identifying appropriate microdata and access requirements."
    },
    {
      "title": "Robert Koch Institute – GEDA Health Monitoring Dataset Collection",
      "url_or_doi": "https://www.rki.de/DE/Aktuelles/Publikationen/Forschungsdaten/FDZ/Datenangebot/GEDA/gesundheit-in-deutschland-aktuell-geda-node.html",
      "justification": "An official collection of German Health Update surveys with methodological documentation, variable inventories, and scientific-use data information. The 2019/2020 survey provides a baseline for evaluating nutrition-related population health during the early 2020s. Relevant for comparing nutrition-associated outcomes between Berlin and other federal states and assessing health inequalities related to food-policy objectives."
    },
    {
      "title": "Berlin Senate Department for Education – Open Education and School Data",
      "url_or_doi": "https://www.berlin.de/sen/bildung/service/daten/",
      "justification": "Berlin's official education open-data portal provides downloadable administrative datasets related to schools and education. It is a useful starting point for identifying data relevant to school nutrition policies, school infrastructure, and the implementation context of public school meal programs. However, the availability of direct indicators on school-meal participation, food quality, or nutrition-policy outcomes must be verified within the catalog."
    },
    {
      "title": "Berlin Steglitz-Zehlendorf – Public Health Monitoring Indicator 5.3.3: Nutrition",
      "url_or_doi": "https://www.berlin.de/ba-steglitz-zehlendorf/politik-und-verwaltung/service-und-organisationseinheiten/qualitaetsentwicklung-planung-und-koordination-im-oeffentlichen-gesundheitsdienst/artikel.1567867.php",
      "justification": "A Berlin district-level public health monitoring resource addressing nutrition policy and institutional food standards. It documents the policy context for nutrition quality standards in daycare and school meals, including Berlin's use of German Nutrition Society standards. Particularly relevant to studying municipal nutrition-policy implementation, although it is an indicator and documentation resource rather than a comprehensive downloadable microdataset."
    }
  ]
}
